```cpp
#include <iostream>
#include <fstream>
#include <cmath>
using namespace std;

bool czyPierwsza(int n) {
    if (n < 2) return false;
    for (int i = 2; i <= sqrt(n); i++)
        if (n % i == 0) return false;
    return true;
}

int main() {
    ifstream plik("liczby.txt");
    int n;
    int ile = 0, suma = 0;
    string lista = "";
    while (plik >> n) {
        if (czyPierwsza(n)) {
            ile++;
            suma += n;
            if (lista != "") lista += " ";
            lista += to_string(n);
        }
    }
    cout << "a) Liczby pierwsze: " << ile << endl;
    cout << "b) Lista: " << lista << endl;
    cout << "c) Suma pierwszych: " << suma << endl;
    return 0;
}
```

**Wyjasnienie**: Funkcja `czyPierwsza` sprawdza podzielnosc od 2 do sqrt(n). Jesli znajdzie dzielnik — zwraca false. W petli glownej zliczamy, sumujemy i zbieramy listke.

